package e.e.a;
public final class PlaybackUrlsTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 public static void main(String[] args){String remote="https://delivery.domand.nicovideo.jp/session/master.m3u8?token=sample&x=1";check(PlaybackUrls.isHls(remote),"authenticated remote playlist");check(PlaybackUrls.isHls("https://example.invalid/MASTER.M3U8"),"case insensitive extension");check(!PlaybackUrls.isHls("https://example.invalid/video.mp4?label=.m3u8"),"query does not change media type");check(remote.equals(PlaybackUrls.directHls("http://127.0.0.1:52862/"+remote)),"unwrap MP4 proxy around HLS");check(remote.equals(PlaybackUrls.directHls("http://localhost:52862/"+remote)),"localhost alias");String cache="http://127.0.0.1:12345/token/cache/sm1.m3u8";check(cache.equals(PlaybackUrls.directHls(cache)),"cache reader preserved");String mp4="http://127.0.0.1:52862/https://example.invalid/movie.mp4";check(mp4.equals(PlaybackUrls.directHls(mp4)),"MP4 proxy preserved");check(remote.equals(PlaybackUrls.directHls(remote)),"direct HLS preserved");check(PlaybackUrls.directHls(null)==null&&!PlaybackUrls.isHls(null),"null safe");check("invalid input".equals(PlaybackUrls.directHls("invalid input")),"invalid URI unchanged");check(remote.equals(CachePlayback.url("http://127.0.0.1:52862/"+remote)),"actual player URL bridge unwraps HLS");check(cache.equals(CachePlayback.url(cache)),"actual player URL bridge preserves cached HLS");check(mp4.equals(CachePlayback.url(mp4)),"actual player URL bridge preserves MP4 proxy");System.out.println("HLS URL routing: 13 compatibility checks passed");}
}
